import Foundation

let filePath = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_ghhvlmy7/graph.json"

guard let data = FileManager.default.contents(atPath: filePath) else {
    fatalError("Cannot read file: \(filePath)")
}

let json = try! JSONSerialization.jsonObject(with: data) as! [String: Any]
let nodes = json["nodes"] as! [String]
let edges = json["edges"] as! [[String: Any]]

var adj: [String: [(String, Double)]] = [:]
for node in nodes {
    adj[node] = []
}

for edge in edges {
    let from = edge["from"] as! String
    let to = edge["to"] as! String
    let weight = (edge["weight"] as! NSNumber).doubleValue
    adj[from]?.append((to, weight))
    adj[to]?.append((from, weight))
}

var dist: [String: Double] = [:]
for node in nodes {
    dist[node] = Double.greatestFiniteMagnitude
}
dist["A"] = 0

var visited: Set<String> = []
var queue: [(String, Double)] = [("A", 0)]

while !queue.isEmpty {
    let minIdx = queue.enumerated().min(by: { $0.element.1 < $1.element.1 })!.offset
    let (node, d) = queue.remove(at: minIdx)

    if visited.contains(node) { continue }
    visited.insert(node)

    if let neighbors = adj[node] {
        for (neighbor, weight) in neighbors {
            let newDist = d + weight
            if newDist < (dist[neighbor] ?? Double.greatestFiniteMagnitude) {
                dist[neighbor] = newDist
                queue.append((neighbor, newDist))
            }
        }
    }
}

func formatDistance(_ d: Double) -> String {
    if d == Double.greatestFiniteMagnitude {
        return "unreachable"
    }
    if d == d.rounded() && abs(d) < 1e15 {
        return "\(Int(d))"
    }
    return "\(d)"
}

print("=== Shortest Paths from A ===")
print("")

let sortedNodes = nodes.sorted()
for node in sortedNodes {
    let d = dist[node] ?? Double.greatestFiniteMagnitude
    print("A -> \(node): \(formatDistance(d))")
}

