import * as fs from 'fs';

interface Edge {
    from: string;
    to: string;
    weight: number;
}

interface Graph {
    nodes: string[];
    edges: Edge[];
}

function dijkstra(graph: Graph, source: string): Map<string, number> {
    const dist = new Map<string, number>();
    const visited = new Set<string>();

    for (const node of graph.nodes) {
        dist.set(node, Infinity);
    }
    dist.set(source, 0);

    const adj = new Map<string, { to: string; weight: number }[]>();
    for (const node of graph.nodes) {
        adj.set(node, []);
    }
    for (const edge of graph.edges) {
        adj.get(edge.from)!.push({ to: edge.to, weight: edge.weight });
        adj.get(edge.to)!.push({ to: edge.from, weight: edge.weight });
    }

    for (let i = 0; i < graph.nodes.length; i++) {
        let u: string | null = null;
        let minDist = Infinity;
        for (const node of graph.nodes) {
            if (!visited.has(node) && dist.get(node)! < minDist) {
                minDist = dist.get(node)!;
                u = node;
            }
        }

        if (u === null) break;

        visited.add(u);

        for (const { to, weight } of adj.get(u)!) {
            if (!visited.has(to)) {
                const newDist = dist.get(u)! + weight;
                if (newDist < dist.get(to)!) {
                    dist.set(to, newDist);
                }
            }
        }
    }

    return dist;
}

const data: Graph = JSON.parse(
    fs.readFileSync('/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_ghhvlmy7/graph.json', 'utf-8')
);

const dist = dijkstra(data, 'A');
const sortedNodes = [...data.nodes].sort();

process.stdout.write('=== Shortest Paths from A ===\n');
process.stdout.write('\n');
for (const node of sortedNodes) {
    const d = dist.get(node)!;
    const formatted = Number.isInteger(d) ? d.toString() : d.toString();
    process.stdout.write(`A -> ${node}: ${formatted}\n`);
}

