let filePath = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_ghhvlmy7/employees.csv"

guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else {
    FileHandle.standardError.write("Error: Could not read file\n".data(using: .utf8)!)
    exit(1)
}

var lines = content.components(separatedBy: "\n").map { $0.replacingOccurrences(of: "\r", with: "") }
lines = lines.filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

guard lines.count > 1 else {
    print("=== Salary Report ===")
    print("")
    print("Average Salary by Department:")
    print("")
    print("Highest Paid: ")
    print("")
    print("Departments with >2 employees:")
    print("")
    print("Total Budget: $0")
    exit(0)
}

let dataLines = Array(lines.dropFirst())

var deptSalaries: [String: [Double]] = [:]
var deptCounts: [String: Int] = [:]
var totalBudget: Double = 0
var highestName = ""
var highestSalary: Double = -1

for line in dataLines {
    let fields = line.components(separatedBy: ",")
    guard fields.count >= 6 else { continue }
    let name = fields[1].trimmingCharacters(in: .whitespaces)
    let dept = fields[2].trimmingCharacters(in: .whitespaces)
    let salaryStr = fields[3].trimmingCharacters(in: .whitespaces)
    guard let salary = Double(salaryStr) else { continue }

    if deptSalaries[dept] == nil {
        deptSalaries[dept] = []
    }
    deptSalaries[dept]?.append(salary)
    deptCounts[dept, default: 0] += 1
    totalBudget += salary

    if salary > highestSalary {
        highestSalary = salary
        highestName = name
    }
}

func formatComma(_ value: Double, decimals: Int) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.minimumFractionDigits = decimals
    formatter.maximumFractionDigits = decimals
    formatter.groupingSeparator = ","
    formatter.groupingSize = 3
    return formatter.string(from: NSNumber(value: value)) ?? "0"
}

