public class Main {
    public static void main(String[] args) throws Exception {
        URL url = new URL("http://127.0.0.1:18923/api/products");
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");
        conn.setConnectTimeout(10000);
        conn.setReadTimeout(10000);

        BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream(), "UTF-8"));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line);
        }
        reader.close();
        conn.disconnect();

        String json = sb.toString();

        List<String[]> products = new ArrayList<>();
        int i = 0;
        while (i < json.length()) {
            if (json.charAt(i) == '{') {
                int depth = 0;
                int start = i;
                while (i < json.length()) {
                    char c = json.charAt(i);
                    if (c == '{') depth++;
                    else if (c == '}') {
                        depth--;
                        if (depth == 0) break;
                    }
                    i++;
                }
                String obj = json.substring(start, i + 1);
                String name = extractString(obj, "name");
                double price = extractNumber(obj, "price");
                products.add(new String[]{name, String.valueOf(price)});
            }
            i++;
        }

        List<String[]> filtered = new ArrayList<>();
        for (String[] p : products) {
            if (Double.parseDouble(p[1]) > 50.00) {
                filtered.add(p);
            }
        }

        filtered.sort((a, b) -> a[0].compareTo(b[0]));

        System.out.println("=== Filtered Products (price > $50.00) ===");
        System.out.println();
        for (String[] p : filtered) {
            System.out.printf("%s: $%.2f\n", p[0], Double.parseDouble(p[1]));
        }
        System.out.println();
        double total = 0;
        for (String[] p : filtered) {
            total += Double.parseDouble(p[1]);
        }
        System.out.println("Count: " + filtered.size());
        System.out.printf("Total: $%.2f\n", total);
    }

    static String extractString(String json, String key) {
        String search = "\"" + key + "\"";
        int idx = json.indexOf(search);
        if (idx == -1) return "";
        idx = json.indexOf(":", idx + search.length());
        if (idx == -1) return "";
        idx = json.indexOf("\"", idx + 1);
        if (idx == -1) return "";
        int end = json.indexOf("\"", idx + 1);
        if (end == -1) return "";
        return json.substring(idx + 1, end);
    }

    static double extractNumber(String json, String key) {
        String search = "\"" + key + "\"";
        int idx = json.indexOf(search);
        if (idx == -1) return 0;
        idx = json.indexOf(":", idx + search.length());
        if (idx == -1) return 0;
        idx++;
        while (idx < json.length() && json.charAt(idx) == ' ') idx++;
        int end = idx;
        while (end < json.length() && (Character.isDigit(json.charAt(end)) || json.charAt(end) == '.' || json.charAt(end) == '-' || json.charAt(end) == 'e' || json.charAt(end) == 'E' || json.charAt(end) == '+')) {
            end++;
        }
        return Double.parseDouble(json.substring(idx, end));
    }
}

