use std::fs;

fn main() {
    let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_ghhvlmy7/app.log";
    let content = fs::read_to_string(path).expect("Failed to read log file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_component_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts: BTreeMap<u32, usize> = BTreeMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        // [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let close_bracket = match line.find(']') {
            Some(pos) => pos,
            None => continue,
        };

        // timestamp part is between [ and ]
        let timestamp_part = &line[1..close_bracket];
        // hour is at index 11..13 of "YYYY-MM-DD HH:MM:SS"
        let hour: u32 = timestamp_part.get(11..13)
            .and_then(|h| h.parse().ok())
            .unwrap_or(0);
        *hour_counts.entry(hour).or_insert(0) += 1;

        // After "] "
        let rest = &line[close_bracket + 1..];
        let rest = rest.strip_prefix(' ').unwrap_or(rest);

        // LEVEL is up to next space
        let space_pos = rest.find(' ').unwrap_or(rest.len());
        let level = &rest[..space_pos];
        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        // After LEVEL: " (component) - message"
        let after_level = &rest[space_pos + 1..];
        let open_paren = after_level.find('(').unwrap_or(0);
        let close_paren = after_level.find(')').unwrap_or(open_paren);
        let component = &after_level[open_paren + 1..close_paren];

        // Message: everything after ") - "
        let after_paren = &after_level[close_paren + 1..];
        let message = after_paren.strip_prefix(" - ")
            .unwrap_or_else(|| after_paren.strip_prefix(" -").unwrap_or(after_paren));
        let message = message.trim_start();

        if level == "ERROR" {
            *error_component_counts.entry(component.to_string()).or_insert(0) += 1;
            error_messages.insert(message.to_string());
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let (top_component, top_count) = error_component_counts.iter()
        .max_by_key(|(_, c)| *c)
        .map(|(k, v)| (k.as_str(), *v))
        .unwrap_or(("", 0));
    println!("Component with Most Errors: {} ({} errors)", top_component, top_count);
    println!();

    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();

    let (busiest_hour, busiest_count) = hour_counts.iter()
        .max_by_key(|(_, c)| *c)
        .map(|(h, c)| (*h, *c))
        .unwrap_or((0, 0));
    println!("Busiest Hour: {:02}:00 ({} entries)", busiest_hour, busiest_count);
}

