#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *run_cmd(const char *cmd)
{
    FILE *fp = popen(cmd, "r");
    if (!fp)
        return NULL;

    size_t cap = 1024;
    char *buf = (char *)malloc(cap);
    if (!buf) {
        pclose(fp);
        return NULL;
    }

    size_t len = 0;
    size_t n;
    while ((n = fread(buf + len, 1, cap - len - 1, fp)) > 0) {
        len += n;
        if (len + 1 >= cap) {
            cap *= 2;
            char *tmp = (char *)realloc(buf, cap);
            if (!tmp) {
                free(buf);
                pclose(fp);
                return NULL;
            }
            buf = tmp;
        }
    }
    buf[len] = '\0';
    pclose(fp);

    /* Strip trailing whitespace and newlines */
    while (len > 0 &&
           (buf[len - 1] == '\n' || buf[len - 1] == '\r' ||
            buf[len - 1] == ' '  || buf[len - 1] == '\t')) {
        buf[--len] = '\0';
    }

    return buf;
}

int main(void)
{
    char *hostname = run_cmd("hostname");
    char *os       = run_cmd("uname -s");
    char *arch     = run_cmd("uname -m");
    char *username = run_cmd("whoami");

    if (!hostname) hostname = strdup("unknown");
