import * as fs from 'fs';
import * as path from 'path';

const ROOT = '/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_ghhvlmy7/project_tree';

interface FileInfo {
  relativePath: string;
  lines: number;
  chars: number;
  extension: string;
}

function getExtension(filename: string): string {
  const lastDot = filename.lastIndexOf('.');
  if (lastDot === -1 || lastDot === 0) {
    return '.';
  }
  return filename.substring(lastDot);
}

function countLines(content: Buffer): number {
  if (content.length === 0) return 0;
  let lines = 0;
  for (let i = 0; i < content.length; i++) {
    if (content[i] === 10) lines++;
  }
  if (content[content.length - 1] !== 10) lines++;
  return lines;
}

function walkDir(dir: string, root: string, visited: Set<string>): FileInfo[] {
  const results: FileInfo[] = [];
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return results;
  }

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    const relativePath = path.relative(root, fullPath).split(path.sep).join('/');

    if (entry.isDirectory()) {
      let realPath: string;
      try {
        realPath = fs.realpathSync(fullPath);
      } catch {
        continue;
      }
      if (visited.has(realPath)) continue;
      visited.add(realPath);
      const subResults = walkDir(fullPath, root, visited);
      results.push(...subResults);
    } else if (entry.isFile()) {
      let content: Buffer;
      try {
        content = fs.readFileSync(fullPath);
      } catch {
        continue;
      }
      const lines = countLines(content);
      const chars = content.length;
      const ext = getExtension(entry.name);
      results.push({ relativePath, lines, chars, extension: ext });
    }
  }
  return results;
}

const visited = new Set<string>();
try {
  visited.add(fs.realpathSync(ROOT));
} catch {
  visited.add(ROOT);
}

const files = walkDir(ROOT, ROOT, visited);

const groups = new Map<string, FileInfo[]>();
for (const f of files) {
  if (!groups.has(f.extension)) {
    groups.set(f.extension, []);
  }
