static const char *skip_ws(const char *s) {
    while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
    return s;
}

static const char *parse_json_string(const char *s, char **out) {
    *out = NULL;
    if (*s != '"') return NULL;
    s++;
    size_t cap = 64;
    char *buf = malloc(cap);
    if (!buf) return NULL;
    size_t len = 0;
    while (*s && *s != '"') {
        if (len + 2 >= cap) {
            cap *= 2;
            char *nb = realloc(buf, cap);
            if (!nb) { free(buf); return NULL; }
            buf = nb;
        }
        if (*s == '\\' && s[1]) {
            s++;
            switch (*s) {
                case 'n': buf[len++] = '\n'; break;
                case 't': buf[len++] = '\t'; break;
                case 'r': buf[len++] = '\r'; break;
                case '"': buf[len++] = '"'; break;
                case '\\': buf[len++] = '\\'; break;
                case '/': buf[len++] = '/'; break;
                case 'b': buf[len++] = '\b'; break;
                case 'f': buf[len++] = '\f'; break;
                case 'u': {
                    if (s[1] && s[2] && s[3] && s[4]) {
                        char hex[5] = {s[1], s[2], s[3], s[4], 0};
                        unsigned int cp = (unsigned int)strtoul(hex, NULL, 16);
                        if (cp < 0x80) {
                            buf[len++] = (char)cp;
                        } else if (cp < 0x800) {
                            buf[len++] = (char)(0xC0 | (cp >> 6));
                            if (len + 1 >= cap) { cap *= 2; char *nb = realloc(buf, cap); if (!nb) { free(buf); return NULL; } buf = nb; }
                            buf[len++] = (char)(0x80 | (cp & 0x3F));
                        } else {
                            buf[len++] = (char)(0xE0 | (cp >> 12));
                            if (len + 2 >= cap) { cap *= 2; char *nb = realloc(buf, cap); if (!nb) { free(buf); return NULL; } buf = nb; }
                            buf[len++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                            buf[len++] = (char)(0x80 | (cp & 0x3F));
                        }
                        s += 4;
                    }
                    break;
                }
                default: buf[len++] = *s; break;
            }
        } else {
            buf[len++] = *s;
        }
        s++;
    }
    if (*s != '"') { free(buf); return NULL; }
    buf[len] = '\0';
    *out = buf;
    return s + 1;
}

static const char *parse_json_number(const char *s, double *out) {
    char *end;
    *out = strtod(s, &end);
    if (end == s) return NULL;
    return end;
}

static const char *skip_value(const char *s) {
    s = skip_ws(s);
