    return strcmp(pa->name, pb->name);
}

static const char *skip_ws(const char *s) {
    while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
    return s;
}

static const char *parse_json_string(const char *s, char **out) {
    *out = NULL;
    if (*s != '"') return NULL;
    s++;
    size_t cap = 64;
    char *buf = malloc(cap);
    if (!buf) return NULL;
    size_t len = 0;
    while (*s && *s != '"') {
        if (len + 2 >= cap) {
            cap *= 2;
            char *nb = realloc(buf, cap);
            if (!nb) { free(buf); return NULL; }
            buf = nb;
        }
        if (*s == '\\' && s[1]) {
            s++;
            switch (*s) {
                case 'n': buf[len++] = '\n'; break;
                case 't': buf[len++] = '\t'; break;
                case 'r': buf[len++] = '\r'; break;
                case '"': buf[len++] = '"'; break;
                case '\\': buf[len++] = '\\'; break;
                case '/': buf[len++] = '/'; break;
                case 'b': buf[len++] = '\b'; break;
                case 'f': buf[len++] = '\f'; break;
                case 'u': {
                    if (s[1] && s[2] && s[3] && s[4]) {
                        char hex[5] = {s[1], s[2], s[3], s[4], 0};
                        unsigned int cp = (unsigned int)strtoul(hex, NULL, 16);
                        if (cp < 0x80) {
                            buf[len++] = (char)cp;
                        } else if (cp < 0x800) {
                            buf[len++] = (char)(0xC0 | (cp >> 6));
                            if (len + 1 >= cap) { cap *= 2; char *nb = realloc(buf, cap); if (!nb) { free(buf); return NULL; } buf = nb; }
                            buf[len++] = (char)(0x80 | (cp & 0x3F));
                        } else {
                            buf[len++] = (char)(0xE0 | (cp >> 12));
                            if (len + 2 >= cap) { cap *= 2; char *nb = realloc(buf, cap); if (!nb) { free(buf); return NULL; } buf = nb; }
                            buf[len++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                            buf[len++] = (char)(0x80 | (cp & 0x3F));
                        }
                        s += 4;
                    }
                    break;
                }
                default: buf[len++] = *s; break;
            }
        } else {
            buf[len++] = *s;
        }
        s++;
    }
    if (*s != '"') { free(buf); return NULL; }
    buf[len] = '\0';
    *out = buf;
    return s + 1;
}

static const char *parse_json_number(const char *s, double *out) {
    char *end;
    *out = strtod(s, &end);
    if (end == s) return NULL;
    return end;
}

static const char *skip_value(const char *s) {
    s = skip_ws(s);
    if (*s == '"') {
        s++;
        while (*s && *s != '"') {
            if (*s == '\\') s++;
            s++;
        }
        if (*s == '"') s++;
        return s;
    } else if (*s == '{' || *s == '[') {
        int depth = 0;
        while (*s) {
            if (*s == '{' || *s == '[') depth++;
            else if (*s == '}' || *s == ']') { depth--; if (depth == 0) { s++; break; } }
            else if (*s == '"') { s++; while (*s && *s != '"') { if (*s == '\\') s++; s++; } }
            s++;
        }
        return s;
    } else {
        while (*s && *s != ',' && *s != '}' && *s != ']' && *s != ' ' && *s != '\t' && *s != '\n' && *s != '\r') s++;
        return s;
    }
}

static int parse_products(const char *json, Product **products, int *count) {
    const char *s = skip_ws(json);
    if (*s != '[') return -1;
    s++;

    *count = 0;
    *products = NULL;

    int cap = 16;
    Product *arr = malloc((size_t)cap * sizeof(Product));
    if (!arr) return -1;

    while (1) {
        s = skip_ws(s);
        if (*s == ']') { s++; break; }
        if (*s == ',') { s++; continue; }
        if (*s != '{') break;
        s++;

        Product p;
        p.name = NULL;
        p.price = 0.0;

        while (1) {
            s = skip_ws(s);
            if (*s == '}') { s++; break; }
            if (*s == ',') { s++; continue; }
            if (*s != '"') break;

            char *key;
            s = parse_json_string(s, &key);
            if (!s) { free(key); break; }

            s = skip_ws(s);
            if (*s != ':') { free(key); break; }
            s++;
            s = skip_ws(s);

            if (strcmp(key, "name") == 0) {
                s = parse_json_string(s, &p.name);
            } else if (strcmp(key, "price") == 0) {
                s = parse_json_number(s, &p.price);
            } else {
                s = skip_value(s);
            }
            free(key);

            if (!s) break;
        }

        if (p.name) {
            if (*count >= cap) {
                cap *= 2;
                Product *na = realloc(arr, (size_t)cap * sizeof(Product));
                if (!na) { free(p.name); free(arr); return -1; }
                arr = na;
            }
            arr[(*count)++] = p;
        }
    }

    *products = arr;
    return 0;
}

static char *http_get(const char *host, int port, const char *path) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) return NULL;

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons((unsigned short)port);
    if (inet_pton(AF_INET, host, &addr.sin_addr) != 1) {
        close(sock);
        return NULL;
    }

    if (connect(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        close(sock);
        return NULL;
    }

    char request[1024];
    int rlen = snprintf(request, sizeof(request),
        "GET %s HTTP/1.1\r\nHost: %s:%d\r\nConnection: close\r\n\r\n",
        path, host, port);

    if (send(sock, request, (size_t)rlen, 0) < 0) {
        close(sock);
        return NULL;
    }

    size_t cap = 8192;
    char *buf = malloc(cap);
    if (!buf) { close(sock); return NULL; }
    size_t len = 0;

    for (;;) {
        if (len + 1 >= cap) {
            cap *= 2;
            char *nb = realloc(buf, cap);
            if (!nb) { free(buf); close(sock); return NULL; }
            buf = nb;
        }
        ssize_t n = recv(sock, buf + len, cap - len - 1, 0);
        if (n < 0) { free(buf); close(sock); return NULL; }
        if (n == 0) break;
        len += (size_t)n;
    }
    close(sock);
    buf[len] = '\0';
    return buf;
}

int main(void) {
    char *response = http_get("127.0.0.1", 18923, "/api/products");
    if (!response) {
        fprintf(stderr, "Failed to get response\n");
        return 1;
    }

    char *body = strstr(response, "\r\n\r\n");
    if (body) body += 4;
    else {
        body = strstr(response, "\n\n");
        if (body) body += 2;
        else body = response;
    }

    Product *products = NULL;
    int total = 0;
    if (parse_products(body, &products, &total) != 0) {
        fprintf(stderr, "Failed to parse JSON\n");
        free(response);
        return 1;
    }
    free(response);

    int fcount = 0;
    Product *filtered = malloc((total > 0 ? (size_t)total : 1) * sizeof(Product));
    if (!filtered) {
        for (int i = 0; i < total; i++) free(products[i].name);
        free(products);
        return 1;
    }

    for (int i = 0; i < total; i++) {
        if (products[i].price > 50.00) {
            filtered[fcount++] = products[i];
        } else {
            free(products[i].name);
        }
    }
    free(products);

    qsort(filtered, (size_t)fcount, sizeof(Product), compare_products);

    printf("=== Filtered Products (price > $50.00) ===\n");
    printf("\n");
    for (int i = 0; i < fcount; i++) {
        printf("%s: $%.2f\n", filtered[i].name, filtered[i].price);
    }
    printf("\n");
    printf("Count: %d\n", fcount);
    double total_price = 0.0;
    for (int i = 0; i < fcount; i++) {
        total_price += filtered[i].price;
    }
    printf("Total: $%.2f\n", total_price);

    for (int i = 0; i < fcount; i++) free(filtered[i].name);
    free(filtered);

    return 0;
}
