            let key = self.parse_string();
            self.expect(':');
            let val = self.parse();
            entries.push((key, val));
            self.skip_whitespace();
            if self.peek() == Some(',') {
                self.next_char();
            } else {
                self.expect('}');
                break;
            }
        }
        Json::Object(entries)
    }

    fn parse_array(&mut self) -> Json {
        self.expect('[');
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next_char();
            return Json::Array(items);
        }
        loop {
            let val = self.parse();
            items.push(val);
            self.skip_whitespace();
            if self.peek() == Some(',') {
                self.next_char();
            } else {
