#[derive(Clone, PartialEq)]
struct HeapItem {
    dist: f64,
    node: String,
}

impl Ord for HeapItem {
    fn cmp(&self, other: &Self) -> Ordering {
        other.dist.partial_cmp(&self.dist).unwrap_or(Ordering::Equal)
            .then_with(|| self.node.cmp(&other.node))
    }
}

impl PartialOrd for HeapItem {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn format_dist(d: f64) -> String {
    if d == d.floor() && d.abs() < 1e15 {
        format!("{}", d as i64)
    } else {
        format!("{}", d)
    }
}

fn main() {
    let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_ghhvlmy7/graph.json";
    let content = fs::read_to_string(path).expect("Failed to read graph.json");
    let mut parser = JsonParser::new(&content);
    let json = parser.parse();

    let nodes_json = json.get("nodes").expect("missing nodes");
    let edges_json = json.get("edges").expect("missing edges");

    let nodes: Vec<String> = nodes_json
        .as_array()
        .unwrap()
        .iter()
        .map(|n| n.as_str().unwrap().to_string())
        .collect();

    let mut adj: HashMap<String, Vec<(String, f64)>> = HashMap::new();
    for n in &nodes {
        adj.entry(n.clone()).or_insert(Vec::new());
    }

    for e in edges_json.as_array().unwrap() {
        let from = e.get("from").unwrap().as_str().unwrap().to_string();
        let to = e.get("to").unwrap().as_str().unwrap().to_string();
        let weight = e.get("weight").unwrap().as_f64().unwrap();

        adj.entry(from.clone()).or_insert_with(Vec::new).push((to.clone(), weight));
        adj.entry(to.clone()).or_insert_with(Vec::new).push((from.clone(), weight));
    }

    let source = "A".to_string();
    let mut dist: HashMap<String, f64> = HashMap::new();
    for n in &nodes {
        dist.insert(n.clone(), f64::INFINITY);
    }
    dist.insert(source.clone(), 0.0);

    let mut heap = BinaryHeap::new();
    heap.push(HeapItem {
        dist: 0.0,
        node: source.clone(),
    });

    while let Some(HeapItem { dist: d, node }) = heap.pop() {
        if d > *dist.get(&node).unwrap() {
            continue;
        }
        if let Some(neighbors) = adj.get(&node) {
            for (neighbor, weight) in neighbors {
                let new_dist = d + weight;
                if new_dist < *dist.get(neighbor).unwrap() {
                    dist.insert(neighbor.clone(), new_dist);
                    heap.push(HeapItem {
                        dist: new_dist,
                        node: neighbor.clone(),
                    });
                }
            }
        }
    }

    println!("=== Shortest Paths from A ===");
    println!();

    let mut sorted_nodes = nodes.clone();
    sorted_nodes.sort();

    for n in &sorted_nodes {
        let d = dist.get(n).unwrap();
        println!("A -> {}: {}", n, format_dist(*d));
    }
}
