use std::collections::BTreeMap;
use std::fs;
use std::io::Read;
use std::path::{Path, PathBuf};

fn count_lines_and_chars(path: &Path) -> (usize, usize) {
    let mut buf = Vec::new();
    let mut file = fs::File::open(path)
        .unwrap_or_else(|e| panic!("failed to open {}: {}", path.display(), e));
    file.read_to_end(&mut buf)
        .unwrap_or_else(|e| panic!("failed to read {}: {}", path.display(), e));

    let chars = buf.len();

    if buf.is_empty() {
        return (0, 0);
    }

    let mut lines = buf.iter().filter(|&&b| b == b'\n').count();
    if !buf.last().map(|&b| b == b'\n').unwrap_or(false) {
        lines += 1;
    }

    (lines, chars)
}

fn get_extension(path: &Path) -> String {
    match path.extension() {
        Some(ext) => format!(".{}", ext),
        None => "(none)".to_string(),
    }
}

fn walk_dir(dir: &Path, base: &Path, files: &mut Vec<(String, String, usize, usize)>) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    for entry in entries {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };

        let path: PathBuf = entry.path();

        if path.is_symlink() {
            continue;
        }

        if path.is_dir() {
            walk_dir(&path, base, files);
        } else if path.is_file() {
            let (lines, chars) = count_lines_and_chars(&path);
            let rel = path.strip_prefix(base).unwrap_or(&path);
            let rel_str = rel.to_string_lossy().to_string();
            let ext = get_extension(&path);
            files.push((rel_str, ext, lines, chars));
        }
    }
}

fn main() {
    let base = Path::new("/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_ghhvlmy7/project_tree");

    let mut files: Vec<(String, String, usize, usize)> = Vec::new();
    walk_dir(base, base, &mut files);

    let mut groups: BTreeMap<String, Vec<(String, usize, usize)>> = BTreeMap::new();
    for (rel, ext, lines, chars) in &files {
        groups
            .entry(ext.clone())
            .or_default()
            .push((rel.clone(), *lines, *chars));
    }

    for v in groups.values_mut() {
        v.sort_by(|a, b| a.0.cmp(&b.0));
    }

    println!("=== File Tree Analysis ===");
    println!();

    let mut total_files = 0;
    let mut total_lines = 0;
    let mut total_chars = 0;

    for (ext, file_list) in &groups {
        let n_files = file_list.len();
        let n_lines: usize = file_list.iter().map(|f| f.1).sum();
        let n_chars: usize = file_list.iter().map(|f| f.2).sum();

        total_files += n_files;
        total_lines += n_lines;
        total_chars += n_chars;

        println!("Extension: {}", ext);
        println!("  Files: {}", n_files);
        println!("  Total Lines: {}", n_lines);
        println!("  Total Characters: {}", n_chars);
        for (rel, lines, chars) in file_list {
            println!("    {}: {} lines, {} chars", rel, lines, chars);
        }
    }

    println!();
    println!(
        "Total: {} files, {} lines, {} characters",
        total_files, total_lines, total_chars
    );
}

