#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    char *name;
    char *department;
    double salary;
} Employee;

static int cmp_str(const void *a, const void *b) {
    return strcmp(*(char *const *)a, *(char *const *)b);
}

static void format_comma_int(long long val, char *buf, size_t bufsize) {
    (void)bufsize;
    char tmp[32];
    snprintf(tmp, sizeof(tmp), "%lld", val);
    int len = (int)strlen(tmp);
    int pos = 0, count = 0;
    for (int i = len - 1; i >= 0; i--) {
        if (count > 0 && count % 3 == 0) buf[pos++] = ',';
        buf[pos++] = tmp[i];
        count++;
    }
    buf[pos] = '\0';
}

static void format_comma_double2(double val, char *buf, size_t bufsize) {
    (void)bufsize;
    char tmp[64];
    snprintf(tmp, sizeof(tmp), "%.2f", val);
    char *dot = strchr(tmp, '.');
    int intlen = (int)(dot - tmp);
    int pos = 0, count = 0;
    for (int i = intlen - 1; i >= 0; i--) {
        if (count > 0 && count % 3 == 0) buf[pos++] = ',';
        buf[pos++] = tmp[i];
        count++;
    }
    while (*dot) buf[pos++] = *dot++;
    buf[pos] = '\0';
}

