#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>

static const char *BASE_DIR = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_ghhvlmy7/project_tree";

typedef struct {
    char *relpath;
    long lines;
    long chars;
    char *ext;
} FileInfo;

static int file_count = 0;
static FileInfo **all_files = NULL;
static int all_files_cap = 0;

static void add_file(const char *relpath, long lines, long chars) {
    if (file_count >= all_files_cap) {
        all_files_cap = all_files_cap ? all_files_cap * 2 : 128;
        all_files = (FileInfo **)realloc(all_files, (size_t)all_files_cap * sizeof(FileInfo *));
        if (!all_files) { fprintf(stderr, "OOM\n"); exit(1); }
    }
    FileInfo *f = (FileInfo *)malloc(sizeof(FileInfo));
    if (!f) { fprintf(stderr, "OOM\n"); exit(1); }
    f->relpath = strdup(relpath);
    f->lines = lines;
    f->chars = chars;
    f->ext = NULL;
    all_files[file_count++] = f;
}

static long count_lines(const char *path) {
    FILE *fp = fopen(path, "rb");
    if (!fp) return 0;
    long count = 0;
    int last_was_newline = 0;
    int any_data = 0;
    char buf[8192];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), fp)) > 0) {
        any_data = 1;
        for (size_t i = 0; i < n; i++) {
            if (buf[i] == '\n') {
                count++;
                last_was_newline = 1;
            } else {
                last_was_newline = 0;
            }
        }
    }
    if (any_data && !last_was_newline) count++;
    fclose(fp);
    return count;
}

static void walk(const char *dirpath, const char *relprefix) {
    DIR *d = opendir(dirpath);
    if (!d) return;

    struct dirent *entry;
    while ((entry = readdir(d)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        size_t full_len = strlen(dirpath) + 1 + strlen(entry->d_name) + 1;
        char *fullpath = (char *)malloc(full_len);
        if (!fullpath) { closedir(d); return; }
        snprintf(fullpath, full_len, "%s/%s", dirpath, entry->d_name);

        struct stat st;
        if (lstat(fullpath, &st) != 0) {
            free(fullpath);
            continue;
        }

        if (S_ISLNK(st.st_mode)) {
            free(fullpath);
            continue;
        }

        size_t rel_len = strlen(relprefix) + 1 + strlen(entry->d_name) + 1;
        char *relpath = (char *)malloc(rel_len);
        if (!relpath) { free(fullpath); closedir(d); return; }
        if (relprefix[0] == '\0')
            snprintf(relpath, rel_len, "%s", entry->d_name);
        else
            snprintf(relpath, rel_len, "%s/%s", relprefix, entry->d_name);

        if (S_ISDIR(st.st_mode)) {
            walk(fullpath, relpath);
            free(fullpath);
            free(relpath);
        } else if (S_ISREG(st.st_mode)) {
            long lines = count_lines(fullpath);
            long chars = st.st_size;
            add_file(relpath, lines, chars);
            free(fullpath);
            free(relpath);
        } else {
            free(fullpath);
            free(relpath);
        }
    }
    closedir(d);
}

static char *get_extension(const char *relpath) {
    const char *slash = strrchr(relpath, '/');
    const char *filename = slash ? slash + 1 : relpath;

    const char *dot = strrchr(filename, '.');
    if (dot && dot != filename) {
        return strdup(dot);
    }
    return strdup("(no ext)");
}

static int cmp_file(const void *a, const void *b) {
    const FileInfo *fa = *(const FileInfo * const *)a;
    const FileInfo *fb = *(const FileInfo * const *)b;
    return strcmp(fa->relpath, fb->relpath);
}

static int cmp_ext(const void *a, const void *b) {
    const char *ea = *(const char * const *)a;
    const char *eb = *(const char * const *)b;
    return strcmp(ea, eb);
}

int main(void) {
    walk(BASE_DIR, "");

    for (int i = 0; i < file_count; i++) {
        all_files[i]->ext = get_extension(all_files[i]->relpath);
    }

    printf("=== File Tree Analysis ===\n");
    printf("\n");

    long total_files = 0;
    long total_lines = 0;
    long total_chars = 0;

    if (file_count > 0) {
        char **exts = (char **)malloc((size_t)file_count * sizeof(char *));
        if (!exts) { fprintf(stderr, "OOM\n"); return 1; }
        for (int i = 0; i < file_count; i++) {
            exts[i] = all_files[i]->ext;
        }
        qsort(exts, (size_t)file_count, sizeof(char *), cmp_ext);

        int unique_count = 0;
        for (int i = 0; i < file_count; i++) {
            if (i == 0 || strcmp(exts[i], exts[i - 1]) != 0) {
                exts[unique_count++] = exts[i];
            }
        }

        for (int e = 0; e < unique_count; e++) {
            const char *ext = exts[e];

            int cnt = 0;
            for (int i = 0; i < file_count; i++) {
                if (strcmp(all_files[i]->ext, ext) == 0) cnt++;
            }

            FileInfo **group = (FileInfo **)malloc((size_t)cnt * sizeof(FileInfo *));
            if (!group) { fprintf(stderr, "OOM\n"); return 1; }
            int gi = 0;
            for (int i = 0; i < file_count; i++) {
                if (strcmp(all_files[i]->ext, ext) == 0) {
                    group[gi++] = all_files[i];
                }
            }
            qsort(group, (size_t)cnt, sizeof(FileInfo *), cmp_file);

            long glines = 0, gchars = 0;
            for (int i = 0; i < cnt; i++) {
                glines += group[i]->lines;
                gchars += group[i]->chars;
            }

            printf("Extension: %s\n", ext);
            printf("  Files: %d\n", cnt);
            printf("  Total Lines: %ld\n", glines);
            printf("  Total Characters: %ld\n", gchars);
            for (int i = 0; i < cnt; i++) {
                printf("    %s: %ld lines, %ld chars\n",
                       group[i]->relpath, group[i]->lines, group[i]->chars);
            }

            total_files += cnt;
            total_lines += glines;
            total_chars += gchars;

            free(group);
        }
        free(exts);
    }

    printf("\n");
    printf("Total: %ld files, %ld lines, %ld characters\n",
           total_files, total_lines, total_chars);

    for (int i = 0; i < file_count; i++) {
        free(all_files[i]->relpath);
        free(all_files[i]->ext);
        free(all_files[i]);
    }
    free(all_files);

    return 0;
