        while (p->pos < p->len && isdigit((unsigned char)p->buf[p->pos])) p->pos++;
    }
    int len = p->pos - start;
    char *tmp = (char *)malloc(len + 1);
    memcpy(tmp, p->buf + start, len);
    tmp[len] = '\0';
    double val = strtod(tmp, NULL);
    free(tmp);
    return json_new_number(val);
}

static json_value *parse_array(parser *p) {
    p->pos++;
    json_value *arr = json_new_array();
    skip_ws(p);
    if (p->pos < p->len && p->buf[p->pos] == ']') {
        p->pos++;
        return arr;
    }
    while (1) {
        skip_ws(p);
        json_value *item = parse_value(p);
        json_array_push(arr, item);
        skip_ws(p);
        if (p->pos < p->len && p->buf[p->pos] == ',') {
            p->pos++;
        } else if (p->pos < p->len && p->buf[p->pos] == ']') {
            p->pos++;
            break;
        } else {
            break;
        }
    }
    return arr;
}

static json_value *parse_object(parser *p) {
    p->pos++;
    json_value *obj = json_new_object();
    skip_ws(p);
    if (p->pos < p->len && p->buf[p->pos] == '}') {
        p->pos++;
        return obj;
    }
    while (1) {
        skip_ws(p);
        char *key = parse_string_raw(p);
        if (!key) break;
        skip_ws(p);
        if (p->pos < p->len && p->buf[p->pos] == ':') p->pos++;
        skip_ws(p);
        json_value *val = parse_value(p);
        json_object_add(obj, key, val);
        skip_ws(p);
        if (p->pos < p->len && p->buf[p->pos] == ',') {
            p->pos++;
        } else if (p->pos < p->len && p->buf[p->pos] == '}') {
            p->pos++;
            break;
        } else {
            break;
        }
    }
    return obj;
}

static json_value *parse_value(parser *p) {
    skip_ws(p);
    if (p->pos >= p->len) return json_new_null();
    char c = p->buf[p->pos];
    if (c == '{') return parse_object(p);
    if (c == '[') return parse_array(p);
    if (c == '"') {
        char *s = parse_string_raw(p);
        json_value *v = json_new_string(s ? s : "");
        free(s);
        return v;
    }
    if (c == 't' && p->pos + 3 < p->len && strncmp(p->buf + p->pos, "true", 4) == 0) {
        p->pos += 4;
        return json_new_bool(1);
    }
    if (c == 'f' && p->pos + 4 < p->len && strncmp(p->buf + p->pos, "false", 5) == 0) {
        p->pos += 5;
        return json_new_bool(0);
    }
    if (c == 'n' && p->pos + 3 < p->len && strncmp(p->buf + p->pos, "null", 4) == 0) {
        p->pos += 4;
        return json_new_null();
    }
    if (c == '-' || isdigit((unsigned char)c)) return parse_number(p);
    p->pos++;
    return json_new_null();
}

static json_value *parse_json(const char *data, int len) {
    parser p = { data, 0, len };
