/* Deep equality */
static int json_equal(json_value *a, json_value *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->bool_val == b->bool_val;
        case JSON_NUMBER: return a->number_val == b->number_val;
        case JSON_STRING: return strcmp(a->string_val, b->string_val) == 0;
        case JSON_ARRAY:
            if (a->array.count != b->array.count) return 0;
            for (int i = 0; i < a->array.count; i++) {
                if (!json_equal(a->array.items[i], b->array.items[i])) return 0;
            }
            return 1;
        case JSON_OBJECT:
            if (a->object.count != b->object.count) return 0;
            for (int i = 0; i < a->object.count; i++) {
                int found = 0;
                for (int j = 0; j < b->object.count; j++) {
                    if (strcmp(a->object.pairs[i].key, b->object.pairs[j].key) == 0) {
                        if (!json_equal(a->object.pairs[i].value, b->object.pairs[j].value)) return 0;
                        found = 1;
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
    }
    return 0;
}

/* Deep merge: takes ownership of a and b (caller must not free them afterwards) */
static json_value *deep_merge(json_value *a, json_value *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        json_value *result = json_new_object();
        for (int i = 0; i < a->object.count; i++) {
            char *key = strdup(a->object.pairs[i].key);
            json_object_add(result, key, a->object.pairs[i].value);
        }
        for (int i = 0; i < b->object.count; i++) {
            const char *key = b->object.pairs[i].key;
            int found = -1;
            for (int j = 0; j < result->object.count; j++) {
                if (strcmp(result->object.pairs[j].key, key) == 0) {
                    found = j;
                    break;
                }
            }
            if (found >= 0) {
                json_value *merged = deep_merge(result->object.pairs[found].value, b->object.pairs[i].value);
                json_free(result->object.pairs[found].value);
                result->object.pairs[found].value = merged;
            } else {
                char *k = strdup(key);
                json_object_add(result, k, b->object.pairs[i].value);
            }
        }
        /* Free a and b top-level structures (children are now owned by result) */
        for (int i = 0; i < a->object.count; i++) free(a->object.pairs[i].key);
        free(a->object.pairs);
        free(a);
        for (int i = 0; i < b->object.count; i++) free(b->object.pairs[i].key);
        free(b->object.pairs);
        free(b);
        return result;
    }
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        json_value *result = json_new_array();
        for (int i = 0; i < a->array.count; i++) {
            json_array_push(result, a->array.items[i]);
        }
        for (int i = 0; i < b->array.count; i++) {
            int dup = 0;
            for (int j = 0; j < result->array.count; j++) {
                if (json_equal(result->array.items[j], b->array.items[i])) {
                    dup = 1;
                    break;
                }
            }
            if (!dup) {
                json_array_push(result, b->array.items[i]);
            }
        }
        free(a->array.items);
        free(a);
        free(b->array.items);
        free(b);
        return result;
    }
    /* Scalar or type mismatch: B overrides A */
    free(a);
    return b;
}

/* Print */
static void print_string_escaped(FILE *f, const char *s) {
    fputc('"', f);
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
            case '"': fputs("\\\"", f); break;
            case '\\': fputs("\\\\", f); break;
            case '\b': fputs("\\b", f); break;
            case '\f': fputs("\\f", f); break;
            case '\n': fputs("\\n", f); break;
            case '\r': fputs("\\r", f); break;
            case '\t': fputs("\\t", f); break;
            default:
                if (c < 0x20) {
                    fprintf(f, "\\u%04x", c);
                } else {
                    fputc(c, f);
                }
                break;
        }
    }
    fputc('"', f);
}

static void print_number(FILE *f, double val) {
    if (val == (double)(long long)val && fabs(val) < 9.0e15) {
        fprintf(f, "%lld", (long long)val);
    } else {
        char buf[64];
        snprintf(buf, sizeof(buf), "%.15g", val);
        if (strtod(buf, NULL) != val) {
            snprintf(buf, sizeof(buf), "%.17g", val);
        }
        fprintf(f, "%s", buf);
    }
}

static void print_value(FILE *f, json_value *v, int indent);

static void print_indent(FILE *f, int level) {
    for (int i = 0; i < level; i++) fprintf(f, "  ");
}

static void print_value(FILE *f, json_value *v, int indent) {
    switch (v->type) {
        case JSON_NULL:
            fprintf(f, "null");
            break;
        case JSON_BOOL:
            fprintf(f, v->bool_val ? "true" : "false");
            break;
        case JSON_NUMBER:
            print_number(f, v->number_val);
            break;
        case JSON_STRING:
            print_string_escaped(f, v->string_val);
            break;
        case JSON_ARRAY:
            if (v->array.count == 0) {
                fprintf(f, "[]");
                return;
            }
            fprintf(f, "[\n");
            for (int i = 0; i < v->array.count; i++) {
                print_indent(f, indent + 1);
                print_value(f, v->array.items[i], indent + 1);
                if (i < v->array.count - 1) fputc(',', f);
                fputc('\n', f);
            }
            print_indent(f, indent);
            fprintf(f, "]");
            break;
        case JSON_OBJECT:
            if (v->object.count == 0) {
                fprintf(f, "{}");
                return;
            }
            json_pair *sorted = (json_pair *)malloc(v->object.count * sizeof(json_pair));
            memcpy(sorted, v->object.pairs, v->object.count * sizeof(json_pair));
            for (int i = 1; i < v->object.count; i++) {
                json_pair tmp = sorted[i];
                int j = i - 1;
                while (j >= 0 && strcmp(sorted[j].key, tmp.key) > 0) {
                    sorted[j + 1] = sorted[j];
                    j--;
                }
                sorted[j + 1] = tmp;
            }
            fprintf(f, "{\n");
            for (int i = 0; i < v->object.count; i++) {
                print_indent(f, indent + 1);
                print_string_escaped(f, sorted[i].key);
                fprintf(f, ": ");
                print_value(f, sorted[i].value, indent + 1);
                if (i < v->object.count - 1) fputc(',', f);
                fputc('\n', f);
            }
            print_indent(f, indent);
            fprintf(f, "}");
            free(sorted);
            break;
    }
}

