    fseek(f, 0, SEEK_SET);

    if (len <= 0) { fclose(f); return 1; }

    char *buf = malloc((size_t)len + 1);
    if (!buf) { fclose(f); return 1; }
    size_t nread = fread(buf, 1, (size_t)len, f);
    buf[nread] = '\0';
    fclose(f);

    const char *p = skip_ws(buf);
    if (*p != '{') { free(buf); return 1; }
    p++;

    int num_nodes = 0;
    int num_edges = 0;
    char **node_names = NULL;
    Edge *edges = NULL;

    while (1) {
        p = skip_ws(p);
        if (*p == '\0') break;
        if (*p == '}') { p++; break; }
        if (*p == ',') { p++; p = skip_ws(p); if (*p == '}' || *p == '\0') { if(*p=='}') p++; break; } continue; }

        char key[MAX_NAME];
        key[0] = '\0';
        p = parse_string(p, key, MAX_NAME);
        if (!p) { free(buf); return 1; }

        p = skip_ws(p);
        if (*p != ':') { free(buf); return 1; }
        p++;
        p = skip_ws(p);

        if (strcmp(key, "nodes") == 0) {
            if (*p != '[') { free(buf); return 1; }
            p++;

            const char *q = skip_ws(p);
            int count = 0;
            if (*q == ']') { q++; }
            else {
                while (1) {
                    q = skip_ws(q);
                    if (*q == ']') { q++; break; }
                    if (*q == ',') { q++; continue; }
                    if (*q == '\0') break;
                    char tmp[MAX_NAME];
                    tmp[0] = '\0';
                    q = parse_string(q, tmp, MAX_NAME);
                    if (!q) break;
                    count++;
                    q = skip_ws(q);
                }
            }

            num_nodes = count;
            node_names = malloc((size_t)(num_nodes > 0 ? num_nodes : 1) * sizeof(char *));
            for (int i = 0; i < num_nodes; i++) {
                node_names[i] = malloc(MAX_NAME);
                node_names[i][0] = '\0';
            }

            q = skip_ws(p);
            if (*q == ']') { q++; }
            else {
                int i = 0;
                while (1) {
                    q = skip_ws(q);
                    if (*q == ']') { q++; break; }
                    if (*q == ',') { q++; continue; }
                    if (*q == '\0') break;
                    if (i < num_nodes) {
                        q = parse_string(q, node_names[i], MAX_NAME);
                    } else {
                        q = skip_value(q);
                    }
                    if (!q) break;
                    i++;
                    q = skip_ws(q);
                }
            }
            p = q;

        } else if (strcmp(key, "edges") == 0) {
            if (*p != '[') { free(buf); return 1; }
            p++;

            const char *q = skip_ws(p);
            int count = 0;
            if (*q == ']') { q++; }
            else {
                while (1) {
                    q = skip_ws(q);
                    if (*q == ']') { q++; break; }
                    if (*q == ',') { q++; continue; }
                    if (*q == '\0') break;
                    if (*q != '{') break;
                    q++;
                    int depth = 1;
                    while (*q && depth > 0) {
                        if (*q == '{') depth++;
                        else if (*q == '}') depth--;
                        else if (*q == '"') { q++; while (*q && *q != '"') { if (*q == '\\') q++; q++; } }
                        q++;
                    }
                    count++;
                    q = skip_ws(q);
                }
            }

            num_edges = count;
            edges = malloc((size_t)(num_edges > 0 ? num_edges : 1) * sizeof(Edge));
            for (int i = 0; i < num_edges; i++) {
                edges[i].from[0] = '\0';
                edges[i].to[0] = '\0';
                edges[i].weight = 0;
            }

            q = skip_ws(p);
            if (*q == ']') { q++; }
            else {
                int i = 0;
                while (1) {
                    q = skip_ws(q);
                    if (*q == ']') { q++; break; }
                    if (*q == ',') { q++; continue; }
                    if (*q == '\0') break;
                    if (*q != '{') break;
                    q++;

                    while (1) {
                        q = skip_ws(q);
                        if (*q == '}') { q++; break; }
                        if (*q == ',') { q++; continue; }
                        if (*q == '\0') break;

                        char fkey[MAX_NAME];
                        fkey[0] = '\0';
                        q = parse_string(q, fkey, MAX_NAME);
                        if (!q) break;
                        q = skip_ws(q);
                        if (*q != ':') { q++; }
                        q = skip_ws(q);

                        if (i < num_edges) {
                            if (strcmp(fkey, "from") == 0) {
                                q = parse_string(q, edges[i].from, MAX_NAME);
                            } else if (strcmp(fkey, "to") == 0) {
                                q = parse_string(q, edges[i].to, MAX_NAME);
                            } else if (strcmp(fkey, "weight") == 0) {
                                q = parse_number(q, &edges[i].weight);
                            } else {
                                q = skip_value(q);
                            }
                        } else {
                            q = skip_value(q);
                        }
                        if (!q) break;
                        q = skip_ws(q);
                    }
                    i++;
                    q = skip_ws(q);
                }
            }
            p = q;
        } else {
            p = skip_value(p);
            if (!p) break;
        }

        p = skip_ws(p);
    }

    free(buf);

    int source_idx = -1;
    for (int i = 0; i < num_nodes; i++) {
        if (node_names[i] && strcmp(node_names[i], "A") == 0) { source_idx = i; break; }
    }
    if (source_idx == -1) { fprintf(stderr, "Node A not found\n"); return 1; }

    int *adj_count = calloc((size_t)(num_nodes > 0 ? num_nodes : 1), sizeof(int));
    int **adj_neighbor = malloc((size_t)(num_nodes > 0 ? num_nodes : 1) * sizeof(int *));
    long long **adj_weight = malloc((size_t)(num_nodes > 0 ? num_nodes : 1) * sizeof(long long *));
    for (int i = 0; i < num_nodes; i++) {
        adj_neighbor[i] = malloc((size_t)(num_edges > 0 ? num_edges : 1) * sizeof(int));
        adj_weight[i] = malloc((size_t)(num_edges > 0 ? num_edges : 1) * sizeof(long long));
    }

    for (int e = 0; e < num_edges; e++) {
        int from_idx = -1, to_idx = -1;
        for (int i = 0; i < num_nodes; i++) {
            if (from_idx == -1 && node_names[i] && strcmp(node_names[i], edges[e].from) == 0) from_idx = i;
            if (to_idx == -1 && node_names[i] && strcmp(node_names[i], edges[e].to) == 0) to_idx = i;
        }
        if (from_idx == -1 || to_idx == -1) continue;

        adj_neighbor[from_idx][adj_count[from_idx]] = to_idx;
        adj_weight[from_idx][adj_count[from_idx]] = edges[e].weight;
        adj_count[from_idx]++;

        adj_neighbor[to_idx][adj_count[to_idx]] = from_idx;
        adj_weight[to_idx][adj_count[to_idx]] = edges[e].weight;
        adj_count[to_idx]++;
    }

    long long *dist = malloc((size_t)(num_nodes > 0 ? num_nodes : 1) * sizeof(long long));
    int *visited = calloc((size_t)(num_nodes > 0 ? num_nodes : 1), sizeof(int));
    for (int i = 0; i < num_nodes; i++) dist[i] = INF_DIST;
    dist[source_idx] = 0;

    for (int iter = 0; iter < num_nodes; iter++) {
        int u = -1;
        long long min_d = INF_DIST;
        for (int i = 0; i < num_nodes; i++) {
            if (!visited[i] && dist[i] < min_d) { min_d = dist[i]; u = i; }
        }
        if (u == -1) break;
        visited[u] = 1;

        for (int j = 0; j < adj_count[u]; j++) {
            int v = adj_neighbor[u][j];
            if (!visited[v] && dist[u] + adj_weight[u][j] < dist[v]) {
                dist[v] = dist[u] + adj_weight[u][j];
            }
        }
    }

    int *sorted_idx = malloc((size_t)(num_nodes > 0 ? num_nodes : 1) * sizeof(int));
    for (int i = 0; i < num_nodes; i++) sorted_idx[i] = i;
    for (int i = 0; i < num_nodes; i++) {
        for (int j = i + 1; j < num_nodes; j++) {
            if (node_names[sorted_idx[i]] && node_names[sorted_idx[j]] &&
                strcmp(node_names[sorted_idx[i]], node_names[sorted_idx[j]]) > 0) {
                int tmp = sorted_idx[i];
                sorted_idx[i] = sorted_idx[j];
                sorted_idx[j] = tmp;
            }
        }
    }

    printf("=== Shortest Paths from A ===\n\n");
    for (int i = 0; i < num_nodes; i++) {
        int idx = sorted_idx[i];
        printf("A -> %s: %lld\n", node_names[idx], dist[idx]);
    }

    free(sorted_idx);
    free(visited);
    free(dist);
    for (int i = 0; i < num_nodes; i++) {
        free(adj_neighbor[i]);
        free(adj_weight[i]);
        free(node_names[i]);
    }
    free(adj_neighbor);
    free(adj_weight);
    free(adj_count);
    free(node_names);
    free(edges);

    return 0;
}
